import React from 'react';
import toast from 'react-hot-toast';
import { downloadNoEmailCsv, triggerDownload } from '../services/api';
import { Building2, Mail, Download, AlertTriangle } from 'lucide-react';

export default function PartiesWithoutEmail({ parties }) {
  const totalRecords = parties.reduce((sum, p) => sum + p.paymentCount, 0);
  const avgRecords = parties.length ? (totalRecords / parties.length).toFixed(1) : '0.0';

  const handleDownload = async () => {
    try {
      const res = await downloadNoEmailCsv(parties);
      triggerDownload(res.data, 'parties_without_email.csv');
    } catch {
      toast.error('Download failed');
    }
  };

  return (
    <div className="no-email-section">
      {/* Metrics */}
      <div className="summary-grid" style={{ marginBottom: '32px' }}>
        <div className="summary-card glass" style={{ borderLeft: '4px solid var(--warning)' }}>
          <div className="summary-info">
            <h3>{parties.length}</h3>
            <p>Missing Emails</p>
          </div>
        </div>
        <div className="summary-card glass">
          <div className="summary-info">
            <h3>{totalRecords}</h3>
            <p>Pending Records</p>
          </div>
        </div>
        <div className="summary-card glass">
          <div className="summary-info">
            <h3>{avgRecords}</h3>
            <p>Avg / Party</p>
          </div>
        </div>
      </div>

      {/* Party cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '16px', marginBottom: '32px' }}>
        {parties.map((party, i) => (
          <div key={i} className="glass glass-hover" style={{ padding: '20px', borderRadius: '16px', border: '1px solid var(--border-subtle)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '12px' }}>
              <div style={{ color: 'var(--warning)', background: 'var(--warning-bg)', padding: '8px', borderRadius: '10px' }}>
                <Building2 size={20} />
              </div>
              <span style={{ fontWeight: '700', color: 'var(--text)', fontSize: '0.9rem' }}>{party.partyName}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', color: 'var(--text-dim)', marginBottom: '16px' }}>
              <span>Code: <strong style={{ color: 'var(--text)' }}>{party.partyCode}</strong></span>
              <span>Records: <strong style={{ color: 'var(--text)' }}>{party.paymentCount}</strong></span>
            </div>
            <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '0.7rem', color: 'var(--danger)', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              <Mail size={12} /> Contact Info Needed
            </div>
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '40px' }}>
        <button className="btn btn-secondary" style={{ padding: '12px 24px' }} onClick={handleDownload}>
          <Download size={18} /> Export Missing Contacts (CSV)
        </button>
      </div>

      <div className="alert alert-info glass" style={{ borderLeft: '4px solid var(--info)' }}>
        <AlertTriangle size={20} style={{ color: 'var(--info)' }} />
        <div style={{ marginLeft: '12px' }}>
          <strong style={{ display: 'block', marginBottom: '8px', fontSize: '0.9rem' }}>Resolution Steps</strong>
          <ol style={{ fontSize: '0.85rem', color: 'var(--text-muted)', lineHeight: '1.6' }}>
            <li>Update the party email repository using the <strong>Security Upload</strong> above.</li>
            <li>Verify all parties have at least one valid communication channel.</li>
            <li>Re-upload the source payment data to initiate matching.</li>
          </ol>
        </div>
      </div>
    </div>
  );
}
